// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;
import "./storage.sol";

contract Machine{
    Storage public s;

    uint256 public calculateResult;
    address public user;

    event AddedValuesByDelegateCall(uint256 a, uint256 b , bool success);
    event AddedValuesByCall(uint256 a, uint256 b , bool success);

    constructor(Storage addr) public {
        s = addr;
        calculateResult = 0;
    }
    function saveValue(uint x) public returns(bool){
        s.setValue(x);
        return true;
    }
    function getValue() public  view returns (uint){
        return s.val();
    }

    function addValuesWithDelegateCall(address caculator, uint256 a , uint256 b) public returns (uint256){
        (bool success,bytes memory result) = caculator.delegatecall(abi.encodeWithSignature("add(uint256,uint256)", a,b));
        emit AddedValuesByDelegateCall(a, b, success);
        return abi.decode(result, (uint256));
    }

    function addValuesWithCall(address caculator, uint256 a , uint256 b) public returns (uint256){
        (bool success,bytes memory result) = caculator.call(abi.encodeWithSignature("add(uint256,uint256)", a,b));
        emit AddedValuesByDelegateCall(a, b, success);
        return abi.decode(result, (uint256));
    }
}
